    'torso_link', 'head_link', 'left_shoulder_pitch_link', 'left_elbow_link', 'left_wrist_yaw_link', 'left_rubber_hand', 'right_shoulder_pitch_link', 'right_elbow_link', 'right_wrist_yaw_link', 'right_rubber_hand',
