      setOpacity(axesG, seg(t, 7.4, 7.8) * (1 - seg(t, 13.4, 13.6)));
      setOpacity(robAx, seg(t, 7.4, 7.8) * (1 - seg(t, 13.4, 13.6)));
      setOpacity(toe, seg(t, 13.6, 14.0));
      var u = ease(seg(t, 10.6, 12.4));
