      tA.lastChild.textContent = '骨盆低 ' + fmt((ST.gmr.pelvis - ST.height.pelvis) * 100, 0) + ' cm，脚底陷进地面 ' + fmt(-ST.height.sole * 100, 0) + ' cm';
      tB.lastChild.textContent = '踩地时脚底悬空 ' + fmt(ST.legsAsArms.sole * 100, 0) + ' cm';
      var pa = project(a[0], cA);
