    t2.appendChild(svgText(554, 220, '表 II：平均全局位置误差', 'demo-x-ink2', 11));
    t2.appendChild(svgRich(554, 238, '$E_{\\text{g-mpbpe}}$（mm，sim，21 段平均）', { size: 10, cls: 'demo-x-mut', w: 210 }));
    var order = [0, 2, 1, 3];
