    rare.appendChild(svgRich(414, 346, '不到全部 21 段（' + fmt(TOTAL_LEN / 60, 1) + ' 分钟）的 **2%**；所有动作都用同一套权重，', { size: 11, cls: 'demo-x-ink2', w: 350 }));
    rare.appendChild(svgRich(414, 366, '个别动作还得单独调权重。', { size: 11, cls: 'demo-x-ink2', w: 350 }));
